def make_pairs(output_dir: Path) -> dict[str, int]:
    """Write 50 curated paraphrase pairs and 50 region/plan/action/number/entity flips."""
    output_dir.mkdir(parents=True, exist_ok=True)
    positives = [
        {
            "id": f"para-{i * 2 + j:03d}",
            "query_a": anchor,
            "query_b": paraphrase,
            "label": "paraphrase",
        }
        for i, (anchor, *variants) in enumerate(PARAPHRASES)
        for j, paraphrase in enumerate(variants)
    ]
    negatives = [
        {
            "id": f"near-{i * 2 + j:03d}",
            "query_a": prefix + first,
            "query_b": prefix + second,
            "label": "near_miss",
        }
        for i, (first, second) in enumerate(NEAR_MISSES)
        for j, prefix in enumerate(("", "Please tell me: "))
    ]
    for name, rows in (("paraphrase_pairs.jsonl", positives), ("near_miss_pairs.jsonl", negatives)):
        (output_dir / name).write_text(
            "".join(json.dumps(row) + "\n" for row in rows), encoding="utf-8"
        )
    return {"paraphrases": len(positives), "near_misses": len(negatives)}


if __name__ == "__main__":
    print(make_pairs(ROOT / "data" / "cache_pairs"))
